import { addMonths } from '/private/tmp/100-tricks-runs/d50/with/m5-weekly-plans/r5/src/dates.js';

const CYCLE = Object.freeze({ MONTH: 'monthly', YEAR: 'yearly' });
const MONTHS_PER_CHARGE = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 12 };

function nextCharge(sub, today) {
  const step = MONTHS_PER_CHARGE[sub.cycle];
  let n = 0;
  let date = sub.since;
  while (date < today) {
    n += 1;
    date = addMonths(sub.since, n * step);
  }
  return date;
}

const gym = { cycle: 'monthly', since: '2026-09-02' };
const music = { cycle: 'monthly', since: '2026-09-30' };
const today = '2026-10-25';

console.log('Original Gym next charge:', nextCharge(gym, today));
console.log('Original Music next charge:', nextCharge(music, today));
EOF
